// ============================================================
// RevOps Sentinel - Audit Configuration
// Edit the CONFIG block, then everything downstream adapts.
// ============================================================
const CONFIG = {
  stagnantDays: 14,                 // open deals untouched longer than this are "stagnant"
  leadLookbackDays: 30,             // inbound lead window used for the unassigned audit
  inboundLifecycleStages: ['subscriber', 'lead', 'marketingqualifiedlead'],
  weights: { deals: 0.6, leads: 0.4 },       // must sum to 1.0
  thresholds: { healthy: 85, warning: 70 },  // score >= healthy = green, >= warning = yellow, else red
  notifyAlways: true,               // false = only post to Slack when status is not Healthy
  hubspotPortalId: '',              // optional Hub ID; enables clickable HubSpot record links
  topN: 5                           // records listed per section in the Slack message
};

const DAY = 24 * 60 * 60 * 1000;
const now = Date.now();
const staleCutoff = now - CONFIG.stagnantDays * DAY;
const leadSince = now - CONFIG.leadLookbackDays * DAY;

const dealProps = ['dealname', 'amount', 'dealstage', 'pipeline', 'hubspot_owner_id', 'notes_last_updated', 'createdate'];
const contactProps = ['firstname', 'lastname', 'email', 'company', 'lifecyclestage', 'hs_lead_status', 'createdate'];

const openDeal = { propertyName: 'hs_is_closed', operator: 'EQ', value: 'false' };

const queries = {
  // 1) Open deals with no activity since the cutoff (OR: stale activity date, or never touched and older than cutoff)
  staleDeals: {
    filterGroups: [
      { filters: [openDeal, { propertyName: 'notes_last_updated', operator: 'LT', value: String(staleCutoff) }] },
      { filters: [openDeal, { propertyName: 'notes_last_updated', operator: 'NOT_HAS_PROPERTY' }, { propertyName: 'createdate', operator: 'LT', value: String(staleCutoff) }] }
    ],
    sorts: [{ propertyName: 'notes_last_updated', direction: 'ASCENDING' }],
    properties: dealProps,
    limit: 100
  },
  // 2) Denominator: all open deals (limit 1, we only need `total`)
  openDeals: {
    filterGroups: [{ filters: [openDeal] }],
    properties: ['dealname'],
    limit: 1
  },
  // 3) Inbound leads in the lookback window with no owner
  unassignedLeads: {
    filterGroups: [{
      filters: [
        { propertyName: 'hubspot_owner_id', operator: 'NOT_HAS_PROPERTY' },
        { propertyName: 'createdate', operator: 'GTE', value: String(leadSince) },
        { propertyName: 'lifecyclestage', operator: 'IN', values: CONFIG.inboundLifecycleStages }
      ]
    }],
    sorts: [{ propertyName: 'createdate', direction: 'ASCENDING' }],
    properties: contactProps,
    limit: 100
  },
  // 4) Denominator: all inbound leads in the lookback window
  inboundLeads: {
    filterGroups: [{
      filters: [
        { propertyName: 'createdate', operator: 'GTE', value: String(leadSince) },
        { propertyName: 'lifecyclestage', operator: 'IN', values: CONFIG.inboundLifecycleStages }
      ]
    }],
    properties: ['email'],
    limit: 1
  }
};

return [{ json: { config: CONFIG, now, staleCutoff, leadSince, queries } }];

// ============================================================
// RevOps Sentinel - Scoring & Aggregation
// Combines the four parallel HubSpot queries into one health report.
// ============================================================
const cfgItem = $('Build Audit Config').first().json;
const C = cfgItem.config;
const now = cfgItem.now;
const portal = C.hubspotPortalId;

const stale = $('Query Stagnant Deals').first().json;
const open = $('Query Open Deals Total').first().json;
const unassigned = $('Query Unassigned Leads').first().json;
const inbound = $('Query Inbound Leads Total').first().json;

const staleCount = Number(stale.total ?? 0);
const openCount = Number(open.total ?? 0);
const unCount = Number(unassigned.total ?? 0);
const inboundCount = Number(inbound.total ?? 0);

// ---- helpers ----
const ratio = (a, b) => (b > 0 ? Math.min(a / b, 1) : 0);
const pct = (r) => `${Math.round(r * 100)}%`;
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const toMs = (v) => {
  if (v === null || v === undefined || v === '') return null;
  const n = /^\d+$/.test(String(v)) ? Number(v) : Date.parse(v);
  return Number.isFinite(n) ? n : null;
};
const daysAgo = (ms) => (ms ? Math.max(0, Math.floor((now - ms) / 86400000)) : null);
const money = (v) => {
  if (v === null || v === undefined || v === '') return 'no amount';
  const n = Number(v);
  return Number.isFinite(n) ? '$' + n.toLocaleString('en-US', { maximumFractionDigits: 0 }) : 'no amount';
};
const link = (url, label) => (url ? `<${url}|${esc(label)}>` : esc(label));

// ---- records ----
const staleDeals = (stale.results || [])
  .map((d) => {
    const p = d.properties || {};
    const last = toMs(p.notes_last_updated) ?? toMs(p.createdate);
    return {
      id: d.id,
      name: p.dealname || '(unnamed deal)',
      amount: p.amount,
      stage: p.dealstage,
      ownerId: p.hubspot_owner_id || null,
      daysUntouched: daysAgo(last),
      url: portal ? `https://app.hubspot.com/contacts/${portal}/record/0-3/${d.id}` : null
    };
  })
  .sort((a, b) => (b.daysUntouched ?? 0) - (a.daysUntouched ?? 0));

const unassignedLeads = (unassigned.results || [])
  .map((c) => {
    const p = c.properties || {};
    const name = [p.firstname, p.lastname].filter(Boolean).join(' ') || p.email || '(no name)';
    return {
      id: c.id,
      name,
      email: p.email || null,
      company: p.company || null,
      stage: p.lifecyclestage || null,
      ageDays: daysAgo(toMs(p.createdate)),
      url: portal ? `https://app.hubspot.com/contacts/${portal}/record/0-1/${c.id}` : null
    };
  })
  .sort((a, b) => (b.ageDays ?? 0) - (a.ageDays ?? 0));

// ---- health score (100 = perfect) ----
const staleRatio = ratio(staleCount, openCount);
const unassignedRatio = ratio(unCount, inboundCount);
const dealPenalty = staleRatio * 100 * C.weights.deals;
const leadPenalty = unassignedRatio * 100 * C.weights.leads;
const score = Math.max(0, Math.min(100, Math.round(100 - dealPenalty - leadPenalty)));

let status, emoji;
if (score >= C.thresholds.healthy) { status = 'Healthy'; emoji = '🟢'; }
else if (score >= C.thresholds.warning) { status = 'Needs Attention'; emoji = '🟡'; }
else { status = 'Critical'; emoji = '🔴'; }

const shouldNotify = C.notifyAlways || status !== 'Healthy';
const runDate = new Date(now).toISOString().slice(0, 10);

// ---- Slack Block Kit ----
const dealLines = staleDeals.slice(0, C.topN).map((d, i) =>
  `${i + 1}. ${link(d.url, d.name)} · ${money(d.amount)} · *${d.daysUntouched ?? '?'}d* untouched${d.ownerId ? '' : ' · _no owner_'}`
);
const leadLines = unassignedLeads.slice(0, C.topN).map((l, i) =>
  `${i + 1}. ${link(l.url, l.name)}${l.company ? ' · ' + esc(l.company) : ''} · *${l.ageDays ?? '?'}d* waiting`
);

const dealsText = (dealLines.length ? dealLines.join('\n') : '_None. Pipeline is moving._') +
  (staleCount > dealLines.length ? `\n_...and ${staleCount - dealLines.length} more_` : '');
const leadsText = (leadLines.length ? leadLines.join('\n') : '_None. Every inbound lead has an owner._') +
  (unCount > leadLines.length ? `\n_...and ${unCount - leadLines.length} more_` : '');

const blocks = [
  { type: 'header', text: { type: 'plain_text', text: `${emoji} RevOps Sentinel: HubSpot Health ${score}/100`, emoji: true } },
  {
    type: 'section',
    fields: [
      { type: 'mrkdwn', text: `*Status*\n${status}` },
      { type: 'mrkdwn', text: `*Health Score*\n${score}/100` },
      { type: 'mrkdwn', text: `*Stagnant deals (>${C.stagnantDays}d)*\n${staleCount} of ${openCount} open (${pct(staleRatio)})` },
      { type: 'mrkdwn', text: `*Unassigned inbound leads*\n${unCount} of ${inboundCount} (${pct(unassignedRatio)}), last ${C.leadLookbackDays}d` }
    ]
  },
  { type: 'divider' },
  { type: 'section', text: { type: 'mrkdwn', text: `*Stagnant deals, oldest first*\n${dealsText}` } },
  { type: 'section', text: { type: 'mrkdwn', text: `*Unassigned inbound leads, longest waiting first*\n${leadsText}` } },
  {
    type: 'context',
    elements: [{ type: 'mrkdwn', text: `Run ${runDate} · deal penalty -${dealPenalty.toFixed(1)} · lead penalty -${leadPenalty.toFixed(1)} · n8n-revops-sentinel-monitor` }]
  }
];

return [{
  json: {
    runDate,
    score,
    status,
    shouldNotify,
    metrics: {
      openDeals: openCount,
      stagnantDeals: staleCount,
      stagnantRatio: Number(staleRatio.toFixed(4)),
      inboundLeads: inboundCount,
      unassignedLeads: unCount,
      unassignedRatio: Number(unassignedRatio.toFixed(4)),
      dealPenalty: Number(dealPenalty.toFixed(2)),
      leadPenalty: Number(leadPenalty.toFixed(2))
    },
    topStagnantDeals: staleDeals.slice(0, C.topN),
    topUnassignedLeads: unassignedLeads.slice(0, C.topN),
    slackText: `${emoji} HubSpot health ${score}/100 (${status}): ${staleCount} stagnant deals, ${unCount} unassigned inbound leads`,
    slackBlocks: JSON.stringify({ blocks })
  }
}];
